/bin/bash -lc "cd [workspace path] && python3 -c \"
import numpy as np
frames = np.load('source_pixels.npz')['rgb']
def centroids(i):
    f=frames[i].astype(int); R,G,B=f[...,0],f[...,1],f[...,2]
    red=(R>150)&(G<120)&(B<130)&((R-G)>60)
    yel=(R>170)&(G>160)&(B<130)&((R-B)>60)&((G-B)>50)
    out={}
    for name,m in (('red',red),('yel',yel)):
        ys,xs=np.where(m)
        if len(xs): out[name]=(xs.mean(),ys.mean(),len(xs))
    return out
for i in [0,9,17,26,35,43,52,60,69,78,86,95]:
    print(i, centroids(i))
\"
"
